const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=[],entry=null,verdict='',matched=false,miss='';
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()}}
const notice=(text,ok=false)=>$('#notice').innerHTML=text?`<div class="${ok?'success':'warning'}">${esc(text)}</div>`:'';
function node(id,x,y,label,sub,type='',w=205){return `<g class="node ${type}" tabindex="0" role="button" aria-label="${esc(label)}" data-node="${esc(id)}"><rect x="${x}" y="${y}" width="${w}" height="60" rx="${id.startsWith('subject')?20:3}"/><text x="${x+12}" y="${y+25}">${esc(label.length>27?label.slice(0,25)+'…':label)}</text><text x="${x+12}" y="${y+45}" style="font-size:11px">${esc(sub)}</text></g>`}
function draw(){let nodes='',edges='';entries.forEach((e,i)=>nodes+=node('entry:'+e.id,22,60+i*104,e.id,e.kind+(e.replay_status==='recorded'?' / recorded':''),entry?.id===e.id?'selected':''));if(entry){const targets=[['subject:0',entry.subject.name,'Subject','proves about'],...entry.closure.map((f,i)=>['file:'+i,f.path,'Delivered file','delivers']),...entry.requires.map((r,i)=>['require:'+i,r,'Required library','requires']),['toolchain:0',entry.toolchain.replace('leanprover/',''),'Toolchain','requires']];targets.forEach(([id,label,sub,relation],i)=>{let y=35+i*89;nodes+=node(id,390,y,label,sub);const from=90+entries.findIndex(e=>e.id===entry.id)*104;edges+=`<path class="edge ${matched?'active':''}" d="M227 ${from} C300 ${from},310 ${y+30},390 ${y+30}"/><text class="edge-label" x="297" y="${y+24}">${relation}</text>`});nodes+=node('checker',22,88+entries.length*104,entry.check?'Input checker':'No input checker',verdict||'Select to run a check',verdict==='accept'?'accept':verdict==='reject'||verdict==='no_checker'?'reject':'');}
if(miss)nodes+=node('demand',22,193+entries.length*104,miss,'Demand / no matching proof','demand');const height=Math.max(293+entries.length*104,entry?90*(entry.closure.length+entry.requires.length+2)+45:0);$('#graph').innerHTML=`<svg viewBox="0 0 620 ${height}" aria-label="Library dependency graph"><title>Library entries and selected dependencies</title>${edges}${nodes}</svg>`;$('#list').innerHTML=`<table><caption>Library entries</caption><thead><tr><th>Entry</th><th>Replay</th></tr></thead><tbody>${entries.map(e=>`<tr><td><button data-entry="${esc(e.id)}">${esc(e.id)}</button><br>${esc(e.claim)}</td><td>${esc(e.replay_status)}</td></tr>`).join('')}</tbody></table>${entry?`<h3>Selected entry dependencies</h3><ul>${[entry.subject.name,...entry.closure.map(x=>x.path),...entry.requires,entry.toolchain].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}`;document.querySelectorAll('[data-node]').forEach(el=>{const act=()=>selectNode(el.dataset.node);el.onclick=act;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act()}}});document.querySelectorAll('[data-entry]').forEach(el=>el.onclick=()=>openEntry(el.dataset.entry));}
function selectNode(id){if(id.startsWith('entry:'))return openEntry(id.slice(6));if(id==='checker'){$('#checker')?.scrollIntoView({block:'start'});$('#input')?.focus();return}if(id==='demand'){location.hash='demand';return}const [kind,index]=id.split(':');let data=kind==='file'?entry.closure[+index]:kind==='subject'?entry.subject:kind==='require'?{requires:entry.requires[+index]}:{toolchain:entry.toolchain};$('#nodeDetail').innerHTML=`<h3>Selected ${esc(kind)}</h3><pre>${esc(JSON.stringify(data,null,2))}</pre>`;$('#nodeDetail').scrollIntoView({block:'nearest'});}
async function openEntry(id){verdict='';const r=await api('catalog/'+encodeURIComponent(id));if(!r.ok){const summary=entries.find(e=>e.id===id);entry=null;$('#details').innerHTML=`<h2>${esc(id)}</h2><div class="warning">Recorded stub. Not re-run by fvapi.</div><p>${esc(summary?.claim||r.data.detail)}</p><p>Full evidence is unavailable in this mock. Choose another entry to inspect its closure.</p>`;draw();return}entry=r.data;renderEntry();draw()}
function renderEntry(){const e=entry;$('#details').innerHTML=`<span class="muted">${esc(e.kind)} / ${esc(e.id)}</span><h2>${esc(e.title)}</h2><p>${esc(e.claim)}</p>${e.replay.status==='recorded'?'<div class="warning"><strong>Recorded stub. Not re-run by fvapi.</strong><br>This transcript comes from an earlier run, not this service.</div>':'<div class="success">Real replay available. Re-run the bundle to establish your own result.</div>'}<div id="nodeDetail"></div><h3>Statements to match</h3>${e.statements.map(s=>`<p class="muted">${esc(s.name)}<br>${esc(s.file)}:${esc(s.line)}</p><pre>${esc(s.text)}</pre>`).join('')}<h3>Delivered closure</h3>${e.closure.map(f=>`<div class="file"><strong>${esc(f.path)}</strong> <span class="muted">${f.bytes} bytes</span><code>sha256 ${esc(f.sha256)}</code></div>`).join('')}<a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download proof bundle</a><h3>Replay command</h3><pre id="command">${esc(e.replay.command)}</pre><button id="copy">Copy replay command</button><p class="muted">${esc(e.replay.note)}</p><h3>Expected axioms</h3><pre>${esc(e.replay.expect_axioms.join('\n')||'None')}</pre>${e.replay.transcript?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}<h3>Licence and source</h3><dl><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)} / ${esc(t.source)}`).join('<br>'):'No third-party notices.'}</dd><dt>Source repository</dt><dd>${esc(e.source.repo)}</dd><dt>Commit</dt><dd><code>${esc(e.source.commit)}</code></dd><dt>Paths</dt><dd>${e.source.paths.map(esc).join('<br>')}</dd></dl><section id="checker"><h3>Run an input check</h3><p class="muted">The verdict checks this input. It does not replace proof replay.</p><label for="input">Input JSON</label><textarea id="input" spellcheck="false">${esc(JSON.stringify(e.check?.example_input||{},null,2))}</textarea><div class="actions"><button id="runCheck">Run check</button>${e.check?'<button id="changeWeight">Edit one weight</button><button id="resetInput">Reset input</button>':''}</div><div id="result" role="status"></div></section>`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy').textContent='Command copied'}catch{$('#copy').textContent='Select the command above to copy it'}};$('#runCheck').onclick=runCheck;if(e.check){$('#changeWeight').onclick=()=>{try{const v=JSON.parse($('#input').value);v.rows[0].weights[0]+=1;$('#input').value=JSON.stringify(v,null,2)}catch{notice('Input is not valid JSON. Correct the input before editing a weight.')}};$('#resetInput').onclick=()=>$('#input').value=JSON.stringify(e.check.example_input,null,2)}}
async function lookup(value){$('#spec').value=value;const r=await api('lookup',{spec_id:value});if(r.ok){matched=true;miss='';await openEntry(r.data.entry_id||r.data.entry.id);notice('Match found. The highlighted path connects the entry to its evidence.',true)}else{matched=false;miss=value;notice(r.status===404?'No match. Logged as demand. Try another specification or inspect Demand.':r.data.detail);draw()}}
async function runCheck(){let input;try{input=JSON.parse($('#input').value)}catch{$('#result').innerHTML='<div class="warning">Input is not valid JSON. Correct the JSON and run the check again.</div>';return}const r=await api('checks/'+encodeURIComponent(entry.id),input);verdict=r.data.verdict||r.data.error;$('#result').innerHTML=`<div class="${verdict==='accept'?'success':'warning'}"><strong>${r.status===409?'No runnable checker. Choose a checker entry.':r.ok?'Check '+verdict:r.data.detail}</strong></div><pre>${esc(JSON.stringify(r.data,null,2))}</pre>`;draw()}
async function activity(type){const r=await api(type);$('#activity').innerHTML=`<h2>${type==='demand'?'Demand: unmatched requests':'Answer log'}</h2><p>${type==='demand'?'Misses remain requests for library work. No agent runs at request time.':'Lookup and check answers returned by the service.'}</p>${type==='demand'?'<h3>Counts by key</h3><pre>'+esc(JSON.stringify(r.data.by_key,null,2))+'</pre>':''}<h3>${type==='demand'?'Misses, newest first':'Answers, newest first'}</h3><pre>${esc(JSON.stringify(r.data[type==='demand'?'misses':'answers'],null,2))}</pre>`;}
async function route(){const state=location.hash.slice(1)||'catalog';$('#library').hidden=['demand','answers'].includes(state);$('#activity').hidden=!$('#library').hidden;notice('');if(['demand','answers'].includes(state)){await activity(state);return}if(state==='catalog'){await openEntry(entries[0].id);return}await openEntry(state==='recorded'||state==='check-409'?'fva.glm-iround':'vf.contrast-2x2');if(state==='lookup-hit')await lookup('vf.contrast-2x2');if(state==='lookup-miss')await lookup('unproved.example');if(state.startsWith('check-')){if(state==='check-reject')$('#changeWeight').click();await runCheck();$('#checker').scrollIntoView({block:'start'})}}
$('#lookup').onsubmit=e=>{e.preventDefault();$('#library').hidden=false;$('#activity').hidden=true;lookup($('#spec').value)};$('#graphView').onclick=()=>view(false);$('#listView').onclick=()=>view(true);function view(list){$('#list').hidden=!list;$('#graph').hidden=list;$('#listView').setAttribute('aria-pressed',list);$('#graphView').setAttribute('aria-pressed',!list)}window.addEventListener('hashchange',()=>route().catch(e=>notice(e.message)));(async()=>{entries=(await api('catalog')).data.entries;await route();if(matchMedia('(max-width:850px)').matches)view(true);document.body.dataset.ready='true'})().catch(e=>notice('The API could not load. Check the connection and reload. '+e.message));
